usage.c:
int i, s = 0;
for (i = 1; i <= 5; i++) {
    if (i == 3) continue;   /* 跳过 3 */
    if (i == 5) break;      /* 到 5 结束 */
    s += i;                 /* 1+2+4 = 7 */
}

usage.cpp:
