usage.c:
struct Node *reverse(struct Node *h) {
    struct Node *pre = NULL;
    while (h) { struct Node *n = h->next; h->next = pre; pre = h; h = n; }
    return pre;
}

usage.cpp:
Node* reverse(Node* h) {
    Node* pre = nullptr;
    while (h) { Node* n = h->next; h->next = pre; pre = h; h = n; }
    return pre;
}

usage.python:
def reverse(h):
    pre = None
    while h:
        h.next, pre, h = pre, h, h.next
    return pre

